// Thin typed client over the backend API. All requests go through the /api
// prefix so the Vite dev proxy (vite.config.ts) and nginx (Dockerfile) can
// route them without the browser knowing the backend origin.

export type Health = { status: string }

export async function fetchHealth(): Promise<Health> {
  const res = await fetch('/api/health')
  if (!res.ok) throw new Error(`HTTP ${res.status}`)
  return (await res.json()) as Health
}

/// <reference types="vitest/config" />
import vue from '@vitejs/plugin-vue'
import { defineConfig } from 'vite'

// https://vite.dev/config/
export default defineConfig({
  plugins: [vue()],
  build: {
    // Audits flag public source maps as an information-disclosure finding.
    sourcemap: false,
  },
  server: {
    // Dev-only: forward /api to the backend so the browser stays same-origin.
    proxy: {
      '/api': {
        target: process.env.VITE_API_URL ?? 'http://localhost:8000',
        changeOrigin: true,
      },
    },
  },
  test: {
    environment: 'jsdom',
    globals: false,
    coverage: {
      provider: 'v8',
      reporter: ['text', 'lcov'],
      include: ['src/**/*.{ts,vue}'],
      exclude: ['src/main.ts', 'src/**/*.test.ts'],
      // Threshold is the signal the test-quality audit looks for; raise as
      // the app grows, never lower it to make CI green.
      thresholds: { lines: 60, statements: 60 },
    },
  },
})

import { flushPromises, mount } from '@vue/test-utils'
import { afterEach, describe, expect, it, vi } from 'vitest'
import App from './App.vue'

// Mocks at the system boundary (network), not internals — same rule as
// testing.md for the backend.
function mockFetch(body: unknown, ok = true, status = 200) {
  vi.stubGlobal(
    'fetch',
    vi.fn().mockResolvedValue({ ok, status, json: async () => body }),
  )
}

afterEach(() => vi.unstubAllGlobals())

describe('App', () => {
  it('shows backend status when /api/health responds', async () => {
    mockFetch({ status: 'ok' })
    const wrapper = mount(App)
    await flushPromises()
    expect(wrapper.get('[data-testid="health"]').text()).toBe('Backend status: ok')
  })

  it('shows an error when /api/health fails', async () => {
    mockFetch({}, false, 503)
    const wrapper = mount(App)
    await flushPromises()
    expect(wrapper.get('[role="alert"]').text()).toContain('HTTP 503')
  })
})

from __future__ import annotations

from datetime import timedelta

from fastapi import APIRouter, Depends, HTTPException, Request, Response
from pydantic import BaseModel, EmailStr, field_validator
from sqlalchemy.ext.asyncio import AsyncSession

from app.clock import Clock
from app.config import Settings
from app.db import get_db
from app.deps import SESSION_COOKIE, current_user, get_clock, get_settings
from app.models.user import User
from app.services import auth

router = APIRouter(prefix="/auth", tags=["auth"])


class CredentialsRequest(BaseModel):
    email: EmailStr
    password: str

    @field_validator("email", mode="before")
    @classmethod
    def _normalize_email(cls, value: str) -> str:
        return value.strip().lower()


class UserResponse(BaseModel):
    id: int
    email: str
    role: str


@router.post("/register", status_code=201, response_model=UserResponse)
async def register(
    body: CredentialsRequest,
    db: AsyncSession = Depends(get_db),
) -> UserResponse:
    try:
        user = await auth.register(db, body.email, body.password)
    except auth.EmailTakenError:
        raise HTTPException(
            status_code=409, detail="email already registered"
        ) from None
    return UserResponse(id=user.id, email=user.email, role=user.role)


@router.post("/login", response_model=UserResponse)
async def login(
    body: CredentialsRequest,
    response: Response,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
    settings: Settings = Depends(get_settings),
) -> UserResponse:
    ttl = timedelta(days=settings.session_ttl_days)
    try:
        token, user = await auth.login(
            db, body.email, body.password, await clock.now(), ttl
        )
    except auth.InvalidCredentialsError:
        raise HTTPException(
            status_code=401, detail="invalid email or password"
        ) from None
    response.set_cookie(
        SESSION_COOKIE,
        token,
        max_age=int(ttl.total_seconds()),
        httponly=True,
        samesite="lax",
        secure=settings.app_env != "dev",
    )
    return UserResponse(id=user.id, email=user.email, role=user.role)


@router.post("/logout", status_code=204)
async def logout(
    request: Request,
    db: AsyncSession = Depends(get_db),
) -> Response:
    token = request.cookies.get(SESSION_COOKIE)
    if token is not None:
        await auth.logout(db, token)
    response = Response(status_code=204)
    response.delete_cookie(SESSION_COOKIE)
    return response


@router.get("/me", response_model=UserResponse)
async def me(user: User = Depends(current_user)) -> UserResponse:
    return UserResponse(id=user.id, email=user.email, role=user.role)

from __future__ import annotations

from datetime import datetime
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, Field, field_validator, model_validator
from sqlalchemy.ext.asyncio import AsyncSession

from app.clock import Clock
from app.db import get_db
from app.deps import current_user, get_broadcaster, get_clock, require_shop
from app.models.sale import Sale
from app.models.user import User
from app.realtime import Broadcaster
from app.services import cart, sales as sales_service
from app.services.sales import InvalidSaleWindowError, SalePhase

router = APIRouter(prefix="/sales", tags=["sales"])


class SaleCreateRequest(BaseModel):
    title: str = Field(max_length=255)
    price_minor: int = Field(ge=0)
    quantity: int = Field(ge=1)
    timezone: str
    starts_at: datetime
    ends_at: datetime

    @field_validator("timezone")
    @classmethod
    def _validate_timezone(cls, value: str) -> str:
        try:
            ZoneInfo(value)
        except ZoneInfoNotFoundError:
            raise ValueError(f"unknown timezone: {value}") from None
        return value

    @field_validator("starts_at", "ends_at")
    @classmethod
    def _require_naive(cls, value: datetime) -> datetime:
        if value.tzinfo is not None:
            raise ValueError(
                "start/end times must be naive wall-clock; the timezone field carries the zone"
            )
        return value

    @model_validator(mode="after")
    def _check_window(self) -> SaleCreateRequest:
        if self.ends_at <= self.starts_at:
            raise ValueError("ends_at must be after starts_at")
        return self


class SaleResponse(BaseModel):
    id: int
    title: str
    price_minor: int
    quantity: int
    available: int
    starts_at: datetime
    ends_at: datetime
    timezone: str
    phase: SalePhase
    server_now: datetime


def _to_response(sale: Sale, now: datetime) -> SaleResponse:
    return SaleResponse(
        id=sale.id,
        title=sale.title,
        price_minor=sale.price_minor,
        quantity=sale.quantity,
        available=sale.available,
        starts_at=sale.starts_at,
        ends_at=sale.ends_at,
        timezone=sale.timezone,
        phase=sales_service.phase(sale.starts_at, sale.ends_at, now),
        server_now=now,
    )


@router.get("", response_model=list[SaleResponse])
async def list_sales(
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
) -> list[SaleResponse]:
    now = await clock.now()
    return [_to_response(sale, now) for sale in await sales_service.list_sales(db)]


@router.get("/{sale_id}", response_model=SaleResponse)
async def get_sale(
    sale_id: int,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
) -> SaleResponse:
    sale = await sales_service.get_sale(db, sale_id)
    if sale is None:
        raise HTTPException(status_code=404, detail="sale not found")
    return _to_response(sale, await clock.now())


@router.post("", status_code=201, response_model=SaleResponse)
async def create_sale(
    body: SaleCreateRequest,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
    _shop: object = Depends(require_shop),
) -> SaleResponse:
    try:
        sale = await sales_service.create_sale(
            db,
            title=body.title,
            price_minor=body.price_minor,
            quantity=body.quantity,
            tz_name=body.timezone,
            starts_at_local=body.starts_at,
            ends_at_local=body.ends_at,
        )
    except InvalidSaleWindowError:
        raise HTTPException(
            status_code=422,
            detail="ends_at must be after starts_at in the sale's timezone",
        ) from None
    return _to_response(sale, await clock.now())


class ReservationResponse(BaseModel):
    id: int
    sale_id: int
    status: str
    expires_at: datetime


@router.post("/{sale_id}/reserve", status_code=201, response_model=ReservationResponse)
async def reserve(
    sale_id: int,
    db: AsyncSession = Depends(get_db),
    clock: Clock = Depends(get_clock),
    broadcaster: Broadcaster = Depends(get_broadcaster),
    user: User = Depends(current_user),
) -> ReservationResponse:
    try:
        reservation = await cart.reserve(
            db, sale_id, user.id, await clock.now(), broadcaster
        )
    except cart.NotStartedError:
        raise HTTPException(
            status_code=409, detail="sale has not started yet"
        ) from None
    except cart.SaleEndedError:
        raise HTTPException(status_code=409, detail="sale has ended") from None
    except cart.SoldOutError:
        raise HTTPException(status_code=409, detail="sold out") from None
    except cart.AlreadyInCartError:
        raise HTTPException(status_code=409, detail="already in cart") from None
    except cart.SaleNotFoundError:
        raise HTTPException(status_code=404, detail="sale not found") from None
    return ReservationResponse(
        id=reservation.id,
        sale_id=reservation.sale_id,
        status=reservation.status,
        expires_at=reservation.expires_at,
    )

from __future__ import annotations

from enum import StrEnum


class UserRole(StrEnum):
    BUYER = "buyer"
    SHOP = "shop"


class SaleStatus(StrEnum):
    ACTIVE = "active"
    ENDED = "ended"


class ReservationStatus(StrEnum):
    HELD = "held"
    PAYING = "paying"
    SOLD = "sold"
    EXPIRED = "expired"
    RELEASED = "released"
    CLEARED = "cleared"


class OrderStatus(StrEnum):
    PENDING = "pending"
    PAID = "paid"
    CANCELLED = "cancelled"


class PaymentStatus(StrEnum):
    PENDING = "pending"
    APPROVED = "approved"
    DECLINED = "declined"


# Value tuples so the CHECK constraints and partial-index predicates in the
# models are derived from these enums (single source of truth) rather than
# hand-copied string literals that can drift.
USER_ROLE_VALUES = tuple(r.value for r in UserRole)
SALE_STATUS_VALUES = tuple(s.value for s in SaleStatus)
RESERVATION_STATUS_VALUES = tuple(s.value for s in ReservationStatus)
ORDER_STATUS_VALUES = tuple(s.value for s in OrderStatus)
PAYMENT_STATUS_VALUES = tuple(s.value for s in PaymentStatus)

ACTIVE_RESERVATION_VALUES = (
    ReservationStatus.HELD.value,
    ReservationStatus.PAYING.value,
)
PENDING_PAYMENT_VALUE = PaymentStatus.PENDING.value


def sql_in_list(values: tuple[str, ...]) -> str:
    """Render values as the body of a SQL ``IN (...)`` list, e.g. ``'a', 'b'``."""
    return ", ".join(repr(v) for v in values)


# State machine — the single source of truth for which transitions are valid.
# Services enforce these as guarded ``UPDATE ... WHERE status = <from>`` (zero
# rows → 409 or no-op), never by a Python check; see docs/plan.md "Машины
# состояний".
RESERVATION_TRANSITIONS: dict[ReservationStatus, frozenset[ReservationStatus]] = {
    ReservationStatus.HELD: frozenset(
        {
            ReservationStatus.PAYING,
            ReservationStatus.EXPIRED,
            ReservationStatus.RELEASED,
            ReservationStatus.CLEARED,
        }
    ),
    ReservationStatus.PAYING: frozenset(
        {
            ReservationStatus.SOLD,
            ReservationStatus.HELD,
            ReservationStatus.CLEARED,
        }
    ),
}

ORDER_TRANSITIONS: dict[OrderStatus, frozenset[OrderStatus]] = {
    OrderStatus.PENDING: frozenset({OrderStatus.PAID, OrderStatus.CANCELLED}),
}

PAYMENT_TRANSITIONS: dict[PaymentStatus, frozenset[PaymentStatus]] = {
    PaymentStatus.PENDING: frozenset({PaymentStatus.APPROVED, PaymentStatus.DECLINED}),
}

SALE_TRANSITIONS: dict[SaleStatus, frozenset[SaleStatus]] = {
    SaleStatus.ACTIVE: frozenset({SaleStatus.ENDED}),
}

