// stores/sales.ts
export const useSalesStore = defineStore('sales', () => {
  const sales = ref<Sale[]>([])
  const serverNow = ref<number | null>(null)  // epoch ms

  async function fetchSales() { ... }
  function applyEvent(event: RealtimeEvent, payload: RealtimePayload) {
    if (event === 'stock_changed' || event === 'sale_status') fetchSales()
  }
