**Design: a small pub/sub event bus owned by useRealtime.**

```ts
// composables/useRealtime.ts
import { useEventSource } from '@vueuse/core'

export type RealtimeEvent = 'stock_changed' | 'sale_status' | 'order_status'

type Handler = (payload: unknown) => void

let started = false
const listeners = new Map<RealtimeEvent, Set<Handler>>()
const reconnectListeners = new Set<() => void>()

export function onRealtimeEvent(event: RealtimeEvent, handler: Handler): void {
  listeners.get(event)?.add(handler) ?? listeners.set(event, new Set([handler]))
  start()
}

export function onRealtimeReconnect(handler: () => void): void {
  reconnectListeners.add(handler)
}

function start(): void {
  if (started) return
  started = true
  const { event, data, status } = useEventSource<RealtimeEvent[]>(
    '/api/events',
    ['stock_changed', 'sale_status', 'order_status'],
    { autoReconnect: { retries: -1, delay: 1000 } },
