// composables/useRealtime.ts
import { watch, type ShallowRef } from 'vue'
import { useEventSource, type EventSourceStatus } from '@vueuse/core'

export const REALTIME_EVENTS = ['stock_changed', 'sale_status', 'order_status'] as const
export type RealtimeEvent = (typeof REALTIME_EVENTS)[number]

type Listener = (data: unknown) => void

// One connection shared by every store, created on first subscribe.
let connection:
  | {
      status: Readonly<ShallowRef<EventSourceStatus>>
      listeners: Map<RealtimeEvent, Set<Listener>>
      reconnect: Set<Listener>
    }
  | null = null

export function useRealtime() {
  if (!connection) {
    const { event, data, status } = useEventSource<RealtimeEvent[]>(
      '/api/events',
      [...REALTIME_EVENTS],
      { autoReconnect: { retries: -1, delay: 1000 } },
    )
    const listeners = new Map<RealtimeEvent, Set<Listener>>()
    const reconnect = new Set<Listener>()
    watch(event, (name) => {
      if (!name) return
      for (const fn of listeners.get(name) ?? []) fn(data.value)
    })
    watch(status, (current, previous) => {
      if (current === 'OPEN' && previous !== 'OPEN') {
        for (const fn of reconnect) fn()
      }
    })
    connection = { status, listeners, reconnect }
  }
  return {
    on(event: RealtimeEvent, fn: Listener): void {
      const set = connection!.listeners.get(event) ?? new Set<Listener>()
      set.add(fn)
      connection!.listeners.set(event, set)
    },
    onReconnect(fn: Listener): void {
      connection!.reconnect.add(fn)
    },
    status: connection.status,
  }
}
```

This is clean. `useRealtime()` returns `{ on, onReconnect, status }`. First call creates the EventSource; subsequent calls share it.

