    const fetch = vi
      .fn()
      .mockResolvedValueOnce(ok(201, SALE))
      .mockResolvedValueOnce(ok(200, [SALE]))
    vi.stubGlobal('fetch', fetch)
    const store = useShopStore()
    const input = {
      title: 'Sneakers',
      price_minor: 1000,
      quantity: 5,
      timezone: 'Europe/Moscow',
      starts_at: '2026-01-01T03:00',
      ends_at: '2026-01-01T04:00',
    }

